import json,subprocess
with open('/proc/meminfo') as f:
 m={l.split(':')[0]:int(l.split()[1]) for l in f if l.split(':')[0] in ('MemTotal','MemAvailable','SwapTotal','SwapFree')}
print(json.dumps({'memoryKiB':m,'containerMemory':subprocess.check_output(['docker','stats','--no-stream','--format','{{.Name}} {{.MemUsage}}'],universal_newlines=True).splitlines()}))

api=subprocess.check_output(['docker','ps','-q','--filter','label=com.docker.compose.project=researchhub-backend','--filter','label=com.docker.compose.service=researchhub-api'],universal_newlines=True).strip()
assert len(api.splitlines())==1
node="import assert from'node:assert/strict';import{readResearchRuntimeConfig}from'./server/research-runtime/config.mjs';import{runtimeDependencies}from'./server/research-runtime/dependencies.mjs';import{bindRuntimeTransactions,withDeploymentTransaction}from'./server/database/transactions.mjs';let prisma;try{const c=readResearchRuntimeConfig(process.env),tenant='rh-kb-local-b0e2af9d-tenant';assert(c.identity.database==='researchhub'&&c.identity.tenantId===tenant);const{load}=runtimeDependencies(c.core);prisma=new(load('prisma/prisma.service','PrismaService'))();await prisma.app.$connect();await prisma.elevated.$connect();const env=bindRuntimeTransactions({prisma,expected:c.identity});const result=await withDeploymentTransaction(env,'direct',async tx=>{return {now:new Date().toISOString(),workers:c.scope.enabledWorkerKinds,task:await tx.knowledgeImportTask.findFirst({where:{id:'cmwrffrc90003s307g7a50hbu',tenantId:tenant},select:{status:true,sourceFile:{select:{sha256:true,filename:true}},errorCode:true,errorMessage:true,stage:true,progress:true,leaseExpiresAt:true,executionToken:true,workerOwner:true,updatedAt:true}}).then(t=>t&&({...t,executionToken:Boolean(t.executionToken),workerOwner:Boolean(t.workerOwner)}))};},{readOnly:true});console.log(JSON.stringify({status:'hub-production-inspected',databaseWrites:0,modelCalls:0,runtime:c.executionProfile,...result}));}catch(e){console.log(JSON.stringify({status:'stopped',code:'INSPECT_CAPABILITY_FAILED'}));process.exitCode=1}finally{await prisma?.app?.$disconnect();await prisma?.elevated?.$disconnect()}\n"
print(subprocess.check_output(['docker','exec',api,'node','--input-type=module','-e',node],universal_newlines=True))
